Projection.plan_term_years:
def plan_term_years():
    """The level premium period in years of the policy's plan code (D31: one branch per member)."""
    if plan() == Plan.T10:
        return 10
    elif plan() == Plan.T20:
        return 20
    elif plan() == Plan.T30:
        return 30
    else:
        raise ValueError("invalid plan")

Projection.policy_term:
def policy_term():
    """The level premium period in years, from the plan code."""
    return plan_term_years()

Projection.premium_schedule:
def premium_schedule():
    """The premium rates of this policy's plan, sex, class and band, by policy year."""
    return data.premium_rates().loc[(plan(), sex(), rate_class(), band())]
